import{_ as r}from"./chunks/ptz-camera.BFf5oNXY.js";import{_ as e,a as i,b as s,c as t,d as c,e as d,f as o}from"./chunks/rbq10-charger.7uvTks7d.js";import{_ as l}from"./chunks/battery.DVQhiztz.js";import{_ as n}from"./chunks/docking-station.MKYdxThc.js";import{_ as h,o as p,c as m,a5 as u}from"./chunks/framework.CcrBcQWS.js";const A=JSON.parse('{"title":"액세서리","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/product-descriptions/accessories.md","filePath":"ko/manual/product-descriptions/accessories.md","lastUpdated":1787021357000}'),b={name:"ko/manual/product-descriptions/accessories.md"};function g(_,a,f,q,v,y){return p(),m("div",null,[...a[0]||(a[0]=[u('<h1 id="액세서리" tabindex="-1">액세서리 <a class="header-anchor" href="#액세서리" aria-label="Permalink to &quot;액세서리&quot;">​</a></h1><p>RBQ는 현장 임무와 개발 목적에 맞게 로봇의 기능을 확장할 수 있는 다양한 선택형 액세서리를 지원합니다. 센싱, 연산·통신, 전원·충전 항목을 운용 목적에 따라 구성할 수 있습니다.</p><h2 id="sensing" tabindex="-1">센싱 <a class="header-anchor" href="#sensing" aria-label="Permalink to &quot;센싱 {#sensing}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+r+'" alt=""><h3 id="ptz-camera">PTZ Camera<a class="header-anchor" href="#ptz-camera" aria-label="PTZ Camera 링크"></a></h3><p>RBQ 본체에 장착하는 Pan-Tilt-Zoom 카메라입니다. 원격으로 패닝·틸팅·줌 제어가 가능하며, 고해상도 영상 스트리밍을 통해 감시 및 정찰 임무에 활용합니다. GUI와 API에서 모두 제어할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/ptz-camera">상세 사양 →</a></div><div class="rbq-card"><img src="'+e+'" alt=""><h3 id="lidar-mid-360">LIDAR (mid-360)<a class="header-anchor" href="#lidar-mid-360" aria-label="LIDAR (mid-360) 링크"></a></h3><p>Livox MID-360은 반구형 시야(360° × 59°)를 제공하는 소형 3D LiDAR입니다. SLAM, 장애물 탐지, 자율 내비게이션에 활용되며, 이더넷으로 연결됩니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/lidar#mid-360">상세 사양 →</a></div><div class="rbq-card"><img src="'+i+'" alt=""><h3 id="lidar-os1-32">LIDAR (OS1-32)<a class="header-anchor" href="#lidar-os1-32" aria-label="LIDAR (OS1-32) 링크"></a></h3><p>Ouster OS1-32는 32채널 360° 회전형 LiDAR로, 광역 3D 매핑에 적합한 고밀도 포인트 클라우드를 제공합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/lidar#os1-32">상세 사양 →</a></div></div><h2 id="compute-connectivity" tabindex="-1">연산 · 통신 <a class="header-anchor" href="#compute-connectivity" aria-label="Permalink to &quot;연산 · 통신 {#compute-connectivity}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+s+'" alt=""><h3 id="user-pc-module">User-PC Module<a class="header-anchor" href="#user-pc-module" aria-label="User-PC Module 링크"></a></h3><p>RBQ 페이로드 베이 내부에 장착하는 임베디드 연산 보드입니다. 사용자 애플리케이션, AI 추론, 커스텀 센서 처리 등을 로봇 내부에서 직접 실행할 수 있으며, 다양한 I/O 인터페이스를 통해 센서와 연결됩니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/network#onboard-pcs-and-ip-addresses">네트워크 · IP →</a></div><div class="rbq-card"><img src="'+t+'" alt=""><h3 id="hub-module">Hub Module<a class="header-anchor" href="#hub-module" aria-label="Hub Module 링크"></a></h3><p>사용 가능한 <code>12V-LAN</code> 포트 수를 늘려주는 인터페이스 허브입니다. 여러 센서를 동시에 연결해야 하는 페이로드 구성에서 배선을 단순화합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/external-port">외부 포트 →</a></div><div class="rbq-card"><img src="'+c+'" alt=""><h3 id="wifi-lte-gps-module">Wifi Module / LTE/GPS Module<a class="header-anchor" href="#wifi-lte-gps-module" aria-label="Wifi Module / LTE/GPS Module 링크"></a></h3><p>원격 운용을 위한 무선 통신 모듈입니다. WiFi 모듈은 근거리 고대역폭 통신을 지원하고, LTE/GPS 모듈은 광역 셀룰러 연결과 위치 측위 기능을 함께 제공합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/network">네트워크 →</a></div></div><h2 id="power-charging" tabindex="-1">전원 · 충전 <a class="header-anchor" href="#power-charging" aria-label="Permalink to &quot;전원 · 충전 {#power-charging}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+l+'" alt=""><h3 id="battery">Battery<a class="header-anchor" href="#battery" aria-label="Battery 링크"></a></h3><p>RBQ에 사용되는 분리형 배터리입니다. 장시간 연속 운용 시 배터리 교체 후 운용할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/battery">상세 사양 →</a></div><div class="rbq-card"><img src="'+d+'" alt=""><h3 id="battery-charging-tray">Battery Charging Tray<a class="header-anchor" href="#battery-charging-tray" aria-label="Battery Charging Tray 링크"></a></h3><p>배터리 팩을 로봇에서 분리한 상태로 충전하는 2구 트레이입니다. 팩을 장착한 채로 충전하려면 RBQ10 충전기를 사용하세요.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/battery">배터리 사양 →</a></div><div class="rbq-card"><img src="'+o+'" alt=""><h3 id="rbq10-charger">RBQ10 Charger<a class="header-anchor" href="#rbq10-charger" aria-label="RBQ10 Charger 링크"></a></h3><p>로봇 상단의 충전 포트에 직접 연결하는 제공 충전기입니다. 표준 AC 전원을 입력받아 배터리를 장착한 상태로 충전합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/operation/charging">충전 방법 →</a></div><div class="rbq-card"><img src="'+n+'" alt=""><h3 id="docking-station">Docking Station<a class="header-anchor" href="#docking-station" aria-label="Docking Station 링크"></a></h3><p class="rbq-card-badges"><span class="rbq-badge">Dog House · Coming soon</span></p><p>RBQ가 자율적으로 도킹하여 자동 배터리 충전 및 보관이 가능한 도킹 스테이션입니다. 장시간 연속 운용 시 수동 배터리 교체 없이 운용할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/docking-station">상세 사양 →</a></div></div>',8)])])}const D=h(b,[["render",g]]);export{A as __pageData,D as default};
